<#
PabloExchange — Gift Cards installer
Run from the PROJECT ROOT (the folder that contains manage.py), with your
virtualenv active if you use one:

    powershell -ExecutionPolicy Bypass -File .\install_giftcards.ps1

What it does:
  1. Creates the full "giftcards" Django app (models, admin, views, urls,
     services, templates, static files).
  2. Backs up templates\base.html to templates\base.html.bak-giftcards,
     then writes the updated base.html (Gift Cards sidebar link).
  3. Adds 'giftcards' to INSTALLED_APPS in config\settings.py.
  4. Adds the giftcards URL include to config\urls.py.
  5. Runs makemigrations + migrate.
Safe to re-run: existing steps are detected and skipped where possible.
#>

$ErrorActionPreference = 'Stop'
$ProjectRoot = (Get-Location).Path

if (-not (Test-Path (Join-Path $ProjectRoot 'manage.py'))) {
    throw "manage.py not found. Open a terminal in your project root (the folder with manage.py) and run this installer from there. No files were changed."
}

Write-Host "Installing PabloExchange Gift Cards..." -ForegroundColor Green
Write-Host "Project: $ProjectRoot"

$Files = [ordered]@{
    'giftcards\__init__.py' = ''
    'giftcards\admin.py' = ''
    'giftcards\apps.py' = 'ZnJvbSBkamFuZ28uYXBwcyBpbXBvcnQgQXBwQ29uZmlnCgoKY2xhc3MgR2lmdGNhcmRzQ29uZmlnKEFwcENvbmZpZyk6CiAgICBkZWZhdWx0X2F1dG9fZmllbGQgPSAiZGphbmdvLmRiLm1vZGVscy5CaWdBdXRvRmllbGQiCiAgICBuYW1lID0gImdpZnRjYXJkcyIK'
    'giftcards\models.py' = ''
    'giftcards\services.py' = ''
    'giftcards\urls.py' = ''
    'giftcards\views.py' = ''
    'giftcards\migrations\__init__.py' = ''
    'giftcards\static\giftcards\css\giftcards.css' = ''
    'giftcards\static\giftcards\js\giftcards.js' = ''
    'giftcards\templates\giftcards\giftcard_detail.html' = ''
    'giftcards\templates\giftcards\giftcards.html' = ''
    'templates\base.html' = ''
}

foreach ($rel in $Files.Keys) {
    $dest = Join-Path $ProjectRoot $rel
    $dir = Split-Path $dest -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }

    if ($rel -eq 'templates\base.html' -and (Test-Path $dest)) {
        $backup = Join-Path $ProjectRoot 'templates\base.html.bak-giftcards'
        Copy-Item -LiteralPath $dest -Destination $backup -Force
        Write-Host "Backed up base.html -> templates\base.html.bak-giftcards" -ForegroundColor DarkYellow
    }

    $bytes = [Convert]::FromBase64String($Files[$rel])
    [IO.File]::WriteAllBytes($dest, $bytes)
    Write-Host "Wrote $rel"
}

# --- 3) Add 'giftcards' to INSTALLED_APPS -----------------------------------
$settingsPath = Join-Path $ProjectRoot 'config\settings.py'
$sLines = [System.Collections.Generic.List[string]]::new()
$sLines.AddRange([string[]](Get-Content -LiteralPath $settingsPath))

if (-not ($sLines | Where-Object { $_ -match '^\s*["'']giftcards["''],?\s*$' })) {
    $idx = -1
    for ($i = 0; $i -lt $sLines.Count; $i++) {
        if ($sLines[$i] -match '^\s*["'']gifts["''],\s*$') { $idx = $i; break }
    }
    if ($idx -ge 0) {
        $sLines.Insert($idx + 1, "    'giftcards',")
        [IO.File]::WriteAllLines($settingsPath, $sLines, [Text.UTF8Encoding]::new($false))
        Write-Host "Added 'giftcards' to INSTALLED_APPS"
    } else {
        Write-Warning "Could not find the 'gifts' entry in INSTALLED_APPS. Add 'giftcards' to INSTALLED_APPS in config\settings.py manually."
    }
} else {
    Write-Host "INSTALLED_APPS already contains 'giftcards'"
}

# --- 4) Add the giftcards URL include ----------------------------------------
$urlsPath = Join-Path $ProjectRoot 'config\urls.py'
$uLines = [System.Collections.Generic.List[string]]::new()
$uLines.AddRange([string[]](Get-Content -LiteralPath $urlsPath))

if (-not ($uLines | Where-Object { $_ -match 'giftcards\.urls' })) {
    $idx = -1
    for ($i = 0; $i -lt $uLines.Count; $i++) {
        if ($uLines[$i] -match 'gifts\.urls') { $idx = $i; break }
    }
    if ($idx -ge 0) {
        $uLines.Insert($idx + 1, '    path("", include("giftcards.urls")),')
        [IO.File]::WriteAllLines($urlsPath, $uLines, [Text.UTF8Encoding]::new($false))
        Write-Host "Added giftcards URL route to config\urls.py"
    } else {
        Write-Warning "Could not find the gifts URL include. Add path('', include('giftcards.urls')) to config\urls.py manually."
    }
} else {
    Write-Host "config\urls.py already includes giftcards.urls"
}

# --- 5) Migrations ------------------------------------------------------------
try {
    & python manage.py makemigrations giftcards
    if ($LASTEXITCODE -eq 0) { & python manage.py migrate }
} catch {
    Write-Warning "Migration step did not finish: $($_.Exception.Message)"
    Write-Warning "Run these manually: python manage.py makemigrations giftcards   then   python manage.py migrate"
}

Write-Host ""
Write-Host "Done! Gift Cards is installed." -ForegroundColor Green
Write-Host "Next steps:"
Write-Host "  1. python manage.py runserver"
Write-Host "  2. Admin -> Gift card countries / categories / cards: add your data."
Write-Host "  3. Visit /gift-cards/ (or use the new Gift Cards sidebar link)."
Write-Host "  Optional: set GIFT_CARD_WHATSAPP_NUMBER in settings.py to change the WhatsApp number."
